    for i in range(n):
        for j in range(n):
            if grid[i][j] < best:
                best = grid[i][j]
                x, y = i, j

    res = [grid[x][y]]
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for _ in range(k - 1):
        nx = ny = None
        best_neighbor = float('inf')
        for dx, dy in dirs:
